describe('Notification Delete Functionality', () => {
  beforeEach(() => {
    cy.visit('/notifications');
  });

  it('should successfully delete a single notification from the list', () => {
    // Verify notification list is displayed
    cy.get('[data-testid="notification-list"]').should('be.visible');
    cy.get('[data-testid="notification-item"]').should('have.length.greaterThan', 0);

    // Intercept the delete API call
    cy.intercept('DELETE', '/api/notifications/*').as('deleteNotification');

    // Click on a notification to delete
    cy.get('[data-testid="notification-item-1"]').click();

    // Verify delete button appears
    cy.get('[data-testid="delete-button"]').should('be.visible');

    // Click delete button
    cy.get('[data-testid="delete-button"]').click();

    // Verify confirmation modal appears
    cy.get('[data-testid="confirm-delete-modal"]').should('be.visible');

    // Verify confirmation button is visible
    cy.get('[data-testid="confirm-delete-button"]').should('be.visible');

    // Click confirm button
    cy.get('[data-testid="confirm-delete-button"]').click();

    // Verify notification is removed from list
    cy.get('[data-testid="notification-item-1"]').should('not.exist');

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Notification deleted successfully');

    // Verify API call was made
    cy.wait('@deleteNotification').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });
  });

  it('should handle edge case: deleting a notification when list is empty', () => {
    // Verify notification list is empty
    cy.get('[data-testid="notification-list"]').should('be.visible');
    cy.get('[data-testid="notification-item"]').should('not.exist');

    // Click on delete button to trigger empty list error
    cy.get('[data-testid="delete-button"]').click();

    // Verify error message appears
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Cannot delete: No notifications found');

    // Verify delete button is still visible
    cy.get('[data-testid="delete-button"]').should('be.visible');

    // Verify API call was not made
    cy.intercept('DELETE', '/api/notifications/*').as('deleteNotification');
    cy.wait('@deleteNotification').then((interception) => {
      expect(interception.request.method).to.equal('DELETE');
      expect(interception.response.statusCode).to.equal(400);
    });
  });
});
